import{_ as e,o,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Contracts — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contracts — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/contracts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contracts — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/contracts"}]]},"headers":[],"relativePath":"user-guide/contracts.md","filePath":"user-guide/contracts.md","lastUpdated":1786832714000}'),n={name:"user-guide/contracts.md"};function s(i,t,c,l,d,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="contracts-—-user-guide" tabindex="-1">Contracts — User Guide <a class="header-anchor" href="#contracts-—-user-guide" aria-label="Permalink to &quot;Contracts — User Guide&quot;">​</a></h1><h2 id="who-can-use-contracts" tabindex="-1">Who can use Contracts <a class="header-anchor" href="#who-can-use-contracts" aria-label="Permalink to &quot;Who can use Contracts&quot;">​</a></h2><p>Your workspace must have the <strong>Opportunities</strong> module installed, then the <strong>Contracts</strong> module (free from Marketplace — not auto-installed). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code> as needed).</p><p>Without <strong>assign</strong>, you only see contracts assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Contracts</strong> from the sidebar (Sales). Search by title, filter by status, opportunity, or assignee, or toggle <strong>My Contracts</strong>. The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted contract from the row menu</li><li><strong>Delete permanently</strong> requires <code>contracts.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New contract</strong></li><li>Choose the related <strong>Opportunity</strong> (required)</li><li>Optionally link a <strong>Quotation</strong> (only shown when the Quotations module is installed)</li><li>Enter a title, party name, start date (required), optional end date, value, currency, and notes</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>Edit from the row menu or the detail drawer while the contract is still <strong>Draft</strong>. After <strong>Activate</strong>, content fields are locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A contract starts in <strong>Draft</strong>. Move it forward with the status action:</p><ul><li><strong>Activate</strong> (<code>draft → active</code>)</li><li><strong>Expire</strong> (<code>active → expired</code>) or <strong>Terminate</strong> (<code>draft</code>/<code>active → terminated</code>)</li></ul><p>Invalid transitions (e.g. expiring directly from Draft) are rejected with a validation error.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the detail drawer or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the contract</li><li><strong>Activity</strong> — timeline of create, update, assignment, status change, note, and delete/restore events</li></ul>',18)])])}const m=e(n,[["render",s]]);export{h as __pageData,m as default};
